'use strict';
const crypto = require('crypto');
const http = require('http');

// Secure request signing middleware with replay protection
const CONFIG = {
  signingKey: process.env.SIGNING_KEY,
  maxClockSkew: 30000, // 30 seconds
  nonceWindowSize: 10000,
  port: 3000
};

if (!CONFIG.signingKey) throw new Error('SIGNING_KEY required');

// Nonce store for replay protection
class NonceStore {
  constructor(maxSize) {
    this.nonces = new Map();
    this.maxSize = maxSize;
  }

  add(nonce, timestamp) {
    if (this.nonces.size >= this.maxSize) {
      // Evict oldest entries
      const entries = [...this.nonces.entries()];
      entries.sort((a, b) => a[1] - b[1]);
      for (let i = 0; i < entries.length / 2; i++) {
        this.nonces.delete(entries[i][0]);
      }
    }
    this.nonces.set(nonce, timestamp);
  }

  has(nonce) {
    return this.nonces.has(nonce);
  }
}

const nonceStore = new NonceStore(CONFIG.nonceWindowSize);

// Compute HMAC signature for request authentication
function computeSignature(method, path, timestamp, nonce, body) {
  // Pack timestamp into fixed-size buffer for canonical representation
  const tsBuf = Buffer.alloc(4);
  tsBuf.writeUInt32BE(timestamp, 0);

  const signatureBase = Buffer.concat([
    Buffer.from(method, 'utf8'),
    Buffer.from('\n'),
    Buffer.from(path, 'utf8'),
    Buffer.from('\n'),
    tsBuf,
    Buffer.from('\n'),
    Buffer.from(nonce, 'utf8'),
    Buffer.from('\n'),
    Buffer.from(body || '', 'utf8')
  ]);

  return crypto.createHmac('sha256', CONFIG.signingKey)
    .update(signatureBase)
    .digest('hex');
}

// Verify request signature with replay protection
function verifyRequest(req, body) {
  const signature = req.headers['x-signature'];
  const timestamp = parseInt(req.headers['x-timestamp'], 10);
  const nonce = req.headers['x-nonce'];

  if (!signature || !timestamp || !nonce) {
    return { valid: false, reason: 'Missing authentication headers' };
  }

  // Check timestamp freshness (anti-replay)
  const now = Date.now();
  const skew = Math.abs(now - timestamp);
  if (skew > CONFIG.maxClockSkew) {
    return { valid: false, reason: 'Request timestamp too old or too new' };
  }

  // Check nonce uniqueness (anti-replay)
  if (nonceStore.has(nonce)) {
    return { valid: false, reason: 'Nonce already used' };
  }

  // Compute expected signature
  const expected = computeSignature(
    req.method, req.url, timestamp, nonce, body
  );

  // Timing-safe comparison
  const sigBuf = Buffer.from(signature, 'hex');
  const expBuf = Buffer.from(expected, 'hex');

  if (sigBuf.length !== expBuf.length) {
    return { valid: false, reason: 'Invalid signature length' };
  }

  if (!crypto.timingSafeEqual(sigBuf, expBuf)) {
    return { valid: false, reason: 'Signature mismatch' };
  }

  // Record nonce to prevent replay
  nonceStore.add(nonce, timestamp);

  return { valid: true };
}

// Protected resource handlers
const handlers = {
  'GET /api/balance': (req) => {
    return { balance: 10000, currency: 'USD' };
  },
  'POST /api/transfer': (req, body) => {
    const data = JSON.parse(body);
    if (!data.to || !data.amount || data.amount <= 0) {
      return { error: 'Invalid transfer parameters' };
    }
    // Simulate transfer
    return { success: true, txId: crypto.randomUUID(), to: data.to, amount: data.amount };
  },
  'DELETE /api/account': (req) => {
    return { success: true, message: 'Account scheduled for deletion' };
  }
};

const server = http.createServer((req, res) => {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    res.setHeader('Content-Type', 'application/json');

    // Health check - no auth required
    if (req.url === '/health') {
      res.writeHead(200);
      res.end(JSON.stringify({ status: 'ok' }));
      return;
    }

    // Verify request signature
    const verification = verifyRequest(req, body);
    if (!verification.valid) {
      res.writeHead(401);
      res.end(JSON.stringify({ error: verification.reason }));
      return;
    }

    const handlerKey = `${req.method} ${req.url}`;
    const handler = handlers[handlerKey];

    if (!handler) {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Not found' }));
      return;
    }

    try {
      const result = handler(req, body);
      res.writeHead(200);
      res.end(JSON.stringify(result));
    } catch (e) {
      res.writeHead(500);
      res.end(JSON.stringify({ error: 'Internal error' }));
    }
  });
});

server.listen(CONFIG.port);
module.exports = { computeSignature, verifyRequest, server };
